"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5900],{74914:e=>{e.exports=JSON.parse('{"functions":[{"name":"log","desc":"Logs a step of the player\'s run. Does nothing if they aren\'t in the\\nfunnel or already logged it.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"step","desc":"","lua_type":"Step"}],"returns":[],"function_type":"static","source":{"line":67,"path":"src/Server/Features/Minigames/FirstRoundFunnel.luau"}},{"name":"join","desc":"Starts the player\'s run if this is their first session, and logs\\n`JoinedLobby`. Call once their profile has loaded.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[],"function_type":"static","source":{"line":91,"path":"src/Server/Features/Minigames/FirstRoundFunnel.luau"}}],"properties":[],"types":[],"name":"FirstRoundFunnel","desc":"The `FirstRound` analytics funnel: how far a first-session player gets\\nthrough the lobby, the vote and their first round. One run per player per\\nserver session, each step logged at most once.\\n\\nA player is in the funnel only if their profile, read once at\\n[FirstRoundFunnel.join], has no saved wins, rounds or play time.\\n`total_time` is saved on every leave, so it is what marks a first session;\\nreading it once keeps a mid-session receipt save from changing the answer.","realm":["Server"],"source":{"line":17,"path":"src/Server/Features/Minigames/FirstRoundFunnel.luau"}}')}}]);